command:
$ErrorActionPreference="Stop"
$db=New-Object System.Data.OleDb.OleDbConnection('Provider=Search.CollatorDSO.1;Extended Properties="Application=Windows"')
$db.Open()
try{
 $where="FROM SystemIndex WHERE SCOPE='file:C:/Users/Public/Desktop/' AND System.FileName LIKE '%Microsoft Edge%'"
 foreach($column in @("System.ItemPathDisplay","System.ItemUrl")){
  $cmd=$db.CreateCommand()
  $cmd.CommandText="SELECT TOP 1001 "+$column+" "+$where
  $reader=$cmd.ExecuteReader();$count=0
  while($reader.Read()){
   $count++
   $value=[string]$reader.GetValue(0)
   $asPath=($value -match "^[A-Za-z]:\\")
   $prefix=($value.ToLowerInvariant().StartsWith("c:\\users\\public\\desktop\\"))
   $leaf=($value.ToLowerInvariant().Contains("microsoft edge"))
   Write-Host ("INDEX_ROW_KIND="+$column+" LENGTH="+$value.Length+" PATH="+$asPath+" PREFIX="+$prefix+" LEAF="+$leaf+" EXISTS="+(Test-Path -LiteralPath $value))
  }
  $reader.Close()
  Write-Host ("INDEX_QUERY_COLUMN="+$column+" ROWS="+$count)
 }
}finally{$db.Close()}
Write-Host "INDEX_PROPERTY_DIAG=PASS"
